```
    WITH
        lembed('all-MiniLM-L6-v2', 'innovative algorithms in graph theory.') AS ref_vec_0   
    SELECT id, distance(articles.abstract_embedding, ref_vec_0) AS distance
    FROM articles
    ORDER BY distance
    LIMIT 1;
```


